! python3 -c 'import json, os, sys
n = int(sys.argv[1])
f = open("long.jsonl", "w")
w = lambda e: f.write(json.dumps(e) + "\n")
w({"type": "session", "version": 3, "id": "long", "timestamp": "2026-01-01T00:00:00.000Z", "cwd": os.getcwd()})
usage = {"input": 1000, "output": 200, "cacheRead": 0, "cacheWrite": 0, "totalTokens": 1200, "cost": {"input": 0, "output": 0, "cacheRead": 0, "cacheWrite": 0, "total": 0}}
a = lambda content, stop: {"role": "assistant", "content": content, "api": "fake-scripted", "provider": "fake", "model": "scripted", "usage": usage, "stopReason": stop}
parent = None
for k in range(n):
    i, r = divmod(k, 4)
    if r == 0: m = {"role": "user", "content": "Step %d: check the parser and fix handle%d." % (i, i)}
    if r == 1: m = a([{"type": "text", "text": "Let me look at the files first."}, {"type": "toolCall", "id": "call_%d" % i, "name": "bash", "arguments": {"command": "ls -la src"}}], "toolUse")
    if r == 2: m = {"role": "toolResult", "toolCallId": "call_%d" % i, "toolName": "bash", "content": [{"type": "text", "text": "\n".join("-rw-r--r-- 1 user user %d file%d.ts" % (100 + j, j) for j in range(20))}], "isError": False}
    if r == 3: m = a([{"type": "text", "text": "## Step %d\n\nThe function `handle%d` now validates its input.\n\n```ts\nexport function handle%d(input: string): number {\n  return input.trim().length;\n}\n```\n" % (i, i, i)}], "stop")
    m["timestamp"] = 1760000000000 + k * 1000
    w
    parent = "%08x" % k
' 4000
